        isset($core["autoload"]["psr-4"]["AzGuard\\Audit\\"]) && exit(1);
        in_array("AzGuard\\Audit\\AuditServiceProvider", $core["extra"]["laravel"]["providers"] ?? [], true) && exit(1);
